import java.util.Stack;

public class Main {
    public static void main(String[] args) {

        Stack<Integer> stack = new Stack<>();

        // PUSH
        stack.push(10);
        stack.push(20);
        stack.push(30);

        // PEEK
        System.out.println("Top element: " + stack.peek());

        // POP
        System.out.println("Popped: " + stack.pop());

        // isEmpty
        if (stack.isEmpty()) {
            System.out.println("Stack is empty");
        } else {
            System.out.println("Stack is not empty");
        }
    }
}

class StackArray {
    int[] stack;
    int top;
    int size;

    StackArray(int size) {
        this.size = size;
        stack = new int[size];
        top = -1;
    }

    void push(int value) {
        if (top == size - 1) {
            System.out.println("Overflow");
            return;
        }
        stack[++top] = value;
    }

    void pop() {
        if (top == -1) {
            System.out.println("Underflow");
            return;
        }
        System.out.println("Popped: " + stack[top--]);
    }

    void peek() {
        if (top == -1) {
            System.out.println("Empty");
            return;
        }
        System.out.println("Top: " + stack[top]);
    }

    void isEmpty() {
        System.out.println(top == -1 ? "Empty" : "Not Empty");
    }
}

class StackLinkedList {

    class Node {
        int data;
        Node next;

        Node(int data) {
            this.data = data;
            this.next = null;
        }
    }

    Node top;

    void push(int value) {
        Node newNode = new Node(value);
        newNode.next = top;
        top = newNode;
    }

    void pop() {
        if (top == null) {
            System.out.println("Underflow");
            return;
        }
        System.out.println("Popped: " + top.data);
        top = top.next;
    }

    void peek() {
        if (top == null) {
            System.out.println("Empty");
            return;
        }
        System.out.println("Top: " + top.data);
    }

    void isEmpty() {
        System.out.println(top == null ? "Empty" : "Not Empty");
    }
}

public class Main {
    public static void main(String[] args) {

        // Array Stack
        StackArray arrStack = new StackArray(5);
        arrStack.push(10);
        arrStack.push(20);
        arrStack.peek();
        arrStack.pop();
        arrStack.isEmpty();

        System.out.println("----");

        // Linked List Stack
        StackLinkedList listStack = new StackLinkedList();
        listStack.push(10);
        listStack.push(20);
        listStack.peek();
        listStack.pop();
        listStack.isEmpty();
    }
}

